    void forma_de_pagamento_inexistente_e_recusada(String formaPagamento) {
        recusa(solicitacao(List.of(CAMISETA), "EXPRESSA", null, formaPagamento, 1, "BRONZE", "SUDESTE"),
                CodigoErro.FORMA_PAGAMENTO_INVALIDA);
