import java.math.*;
public class Calc {
  static MathContext MC = MathContext.DECIMAL128;
  static BigDecimal c(BigDecimal x){return x.setScale(2, RoundingMode.HALF_EVEN);}
  public static void main(String[] a){
    BigDecimal t = new BigDecimal("262.29"), i = new BigDecimal("0.0199");
    for (int n : new int[]{1,2,3,4,6,12}) {
      if (n<=3) System.out.println(n+" total="+c(t)+" parcela="+c(t.divide(BigDecimal.valueOf(n),MC)));
      else {
        BigDecimal f = BigDecimal.ONE.add(i).pow(n,MC);
        BigDecimal d = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(f,MC));
        BigDecimal p = c(t.multiply(i).divide(d,MC));
        System.out.println(n+" total="+c(p.multiply(BigDecimal.valueOf(n)))+" parcela="+p);
      }
    }
    // frete economica 3 x 0.015 kg
    System.out.println("frete="+c(new BigDecimal("12.00").add(new BigDecimal("2.00").multiply(new BigDecimal("0.045")))));
    // jaqueta 299.90 x2 = 599.80 ouro credito 5%
    System.out.println("credito="+c(new BigDecimal("599.80").multiply(new BigDecimal("0.05"))));
    // boleto sofa: 999.00 + frete expressa (25+4.5*2=34) + seguro sudeste 9.99 = 1042.99 > 1000
    System.out.println("totalSofa="+c(new BigDecimal("999.00").add(new BigDecimal("34.00")).add(new BigDecimal("9.99"))));
    // fretegratis bronze expressa: 409.70-33.10+33.10+4.097 -> total 413.80 pix
    BigDecimal tot = new BigDecimal("409.70").subtract(new BigDecimal("33.10")).add(new BigDecimal("33.10")).add(c(new BigDecimal("4.097")));
    System.out.println("totalFG="+c(tot)+" pix="+c(tot.subtract(c(tot.multiply(new BigDecimal("0.05"))))));
    // menos50 calca 300.00 retirada sudeste
    System.out.println("seguroCalca="+c(new BigDecimal("300.00").multiply(new BigDecimal("0.01"))));
  }
}
